const modifier = (text) => {
    let result = text;

    // --------------------------------------------------
    // PLAYER REGISTRATION
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_PLAYER:([^\]]+)\]/gi,
        function(match, name) {
            registerPlayerContinuity(name.trim());
            return "";
        }
    );


    // --------------------------------------------------
    // CHARACTER REGISTRATION
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_CHARACTER:([^\]]+)\]/gi,
        function(match, name) {
            registerContinuityCharacter(name.trim());
            return "";
        }
    );


    // --------------------------------------------------
    // IDENTITY FACTS
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_IDENTITY:([^|\]]+)\|([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, field, value) {
            setContinuityIdentityField(
                name.trim(),
                field.trim().toLowerCase(),
                value.trim(),
                false
            );
            return "";
        }
    );

    result = result.replace(
        /\[CONT_IDENTITY_OVERRIDE:([^|\]]+)\|([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, field, value) {
            setContinuityIdentityField(
                name.trim(),
                field.trim().toLowerCase(),
                value.trim(),
                true
            );
            return "";
        }
    );


    // --------------------------------------------------
    // APPEARANCE FACTS
    // --------------------------------------------------

