        /\[CONT_APPEARANCE_OVERRIDE:([^|\]]+)\|([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, field, value) {
            setContinuityAppearanceField(
                name.trim(),
                field.trim().toLowerCase(),
                value.trim(),
                true
            );
            return "";
        }
    );


