    // SCARS
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_SCAR:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuityScar(
                name.trim(),
                detail.trim()
            );
            return "";
