    result = result.replace(
        /\[CONT_ABILITY:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuityAbility(
                name.trim(),
                detail.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // POWERS
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_POWER:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuityPower(
                name.trim(),
                detail.trim()
            );
            return "";
