    result = result.replace(
        /\[CONT_SKILL:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuitySkill(
                name.trim(),
                detail.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // FAMILY FACTS
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_FAMILY:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuityFamilyFact(
                name.trim(),
                detail.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // IMPORTANT FACTS
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_FACT:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuityImportantFact(
                name.trim(),
                detail.trim()
            );
            return "";
