    result = result.replace(
        /\[CONT_TEMP_REMOVE:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            removeContinuityTemporaryState(
                name.trim(),
                detail.trim()
            );
            return "";
        }
    );

    result = result.replace(
        /\[CONT_TEMP_CLEAR:([^\]]+)\]/gi,
        function(match, name) {
            clearContinuityTemporaryStates(
                name.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // LOCATION
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_LOCATION:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, location) {
            setContinuityLocation(
                name.trim(),
                location.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // ACTIVE SCENE LOCATION
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_SCENE:([^\]]+)\]/gi,
        function(match, location) {
            setContinuitySceneLocation(
                location.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // ENTER SCENE
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_ENTER:([^\]]+)\]/gi,
        function(match, name) {
            continuityEnterScene(
                name.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // LEAVE SCENE
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_LEAVE:([^\]]+)\]/gi,
        function(match, name) {
            continuityLeaveScene(
                name.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // PERCEPTION ABILITIES
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_PERCEPTION_ABILITY:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, ability) {
            addContinuityPerceptionAbility(
                name.trim(),
                ability.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // PERCEPTION DEVICES / METHODS
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_PERCEPTION_DEVICE:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, device) {
            addContinuityPerceptionDevice(
                name.trim(),
                device.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // ACTIVE REMOTE PERCEPTION
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_REMOTE_ADD:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, source) {
            addActiveRemotePerception(
                name.trim(),
                source.trim()
            );
            return "";
        }
    );

    result = result.replace(
        /\[CONT_REMOTE_REMOVE:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, source) {
            removeActiveRemotePerception(
                name.trim(),
                source.trim()
            );
            return "";
        }
    );

    result = result.replace(
        /\[CONT_REMOTE_CLEAR:([^\]]+)\]/gi,
        function(match, name) {
            clearActiveRemotePerception(
                name.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // NOTES
    // --------------------------------------------------

    result = result.replace(
        /\[CONT_NOTE:([^|\]]+)\|([^\]]+)\]/gi,
        function(match, name, detail) {
            addContinuityNote(
                name.trim(),
                detail.trim()
            );
            return "";
        }
    );


    // --------------------------------------------------
    // CLEANUP
    // --------------------------------------------------

    result = result.replace(/\n{3,}/g, "\n\n");
    result = result.trim();

    return { text: result };
};

modifier(text);

code.sharedLibrary:
// CHARACTER CONTINUITY & IDENTITY
// Shared Library
//
// PURPOSE:
//
// Preserve established character identity and location facts.
//
// Prevent:
// - random appearance changes
// - occupation/background drift
// - forgotten player identity
// - characters teleporting into scenes
// - characters overhearing conversations they cannot perceive
// - temporary states replacing permanent identity
//
// COMPATIBILITY:
//
// Uses its own namespace:
// state.characterContinuity
//
// Does NOT overwrite state.memory.
//
// Does NOT attempt to replace specialized systems such as:
// - Player Agency
// - Basic Needs & Health
// - Relationships
// - Pregnancy
// - Beastkin Continuity
// - Universal Time
//
// Specialized scripts remain authoritative for their own domains.


// --------------------------------------------------
// INITIALIZATION
// --------------------------------------------------

function initCharacterContinuity() {
    if (!state.characterContinuity) {
        state.characterContinuity = {
            player: null,
            characters: {},
            activeScene: {
                location: null,
                participants: []
            }
        };
    }

    if (!state.characterContinuity.characters) {
        state.characterContinuity.characters = {};
    }

    if (!state.characterContinuity.activeScene) {
        state.characterContinuity.activeScene = {
            location: null,
            participants: []
        };
    }

    if (!Array.isArray(state.characterContinuity.activeScene.participants)) {
        state.characterContinuity.activeScene.participants = [];
    }

    return state.characterContinuity;
}


// --------------------------------------------------
// NAME NORMALIZATION
// --------------------------------------------------

function normalizeContinuityName(name) {
    if (!name) {
        return "";
    }

    return String(name).trim();
}


// --------------------------------------------------
// UNIQUE ARRAY HELPER
// --------------------------------------------------

function addUniqueContinuityValue(array, value) {
    if (!Array.isArray(array) || !value) {
        return false;
    }

    const cleanValue = String(value).trim();

    if (!cleanValue) {
        return false;
    }

    if (array.indexOf(cleanValue) === -1) {
        array.push(cleanValue);
        return true;
    }

    return false;
}


// --------------------------------------------------
// PLAYER RECORD
// --------------------------------------------------
//
// The player has a dedicated record because their
// established identity receives the strongest protection.
//
// Unknown player characteristics remain unknown.
// The AI should not fill them in merely because they
// have not been specified.

function registerPlayerContinuity(name) {
    const data = initCharacterContinuity();

    const cleanName =
        normalizeContinuityName(name);

    if (!cleanName) {
        return false;
    }

    if (!data.player) {
        data.player = createContinuityRecord(cleanName);
        data.player.isPlayer = true;
        return true;
    }

    return false;
}


function getPlayerContinuity() {
    const data = initCharacterContinuity();

    return data.player || null;
}


// --------------------------------------------------
// GENERIC CHARACTER RECORD
// --------------------------------------------------

function createContinuityRecord(name) {
    return {
        name: name,

        isPlayer: false,

        // Permanent / authoritative identity facts
        identity: {
            age: null,
            gender: null,
            pronouns: null,
            species: null,
            occupation: null,
            background: null,
            orientation: null,
            home: null
        },

        appearance: {
            height: null,
            build: null,
            skin: null,
            hair: null,
            eyes: null,
            scars: [],
            tattoos: [],
            permanentTraits: []
        },

        abilities: [],
        powers: [],
        skills: [],

        familyFacts: [],
        importantFacts: [],

        // Temporary states do not overwrite permanent identity.
        temporaryStates: [],

        // Physical placement
        currentLocation: null,
        lastKnownLocation: null,
        presentInScene: false,

        // Established perception exceptions
        perceptionAbilities: [],
        perceptionDevices: [],

        // Optional scene-specific remote access
        activeRemotePerception: [],

        notes: []
    };
}


// --------------------------------------------------
// REGISTER NPC / OTHER CHARACTER
// --------------------------------------------------

function registerContinuityCharacter(name) {
    const data = initCharacterContinuity();

    const cleanName =
        normalizeContinuityName(name);

    if (!cleanName) {
        return false;
    }

    if (
        data.player &&
        data.player.name === cleanName
    ) {
        return false;
    }

    if (!data.characters[cleanName]) {
        data.characters[cleanName] =
            createContinuityRecord(cleanName);

        return true;
    }

    return false;
}


// --------------------------------------------------
// GET CHARACTER
// --------------------------------------------------

function getContinuityCharacter(name) {
    const data = initCharacterContinuity();

    const cleanName =
        normalizeContinuityName(name);

    if (!cleanName) {
        return null;
    }

    if (
        data.player &&
        data.player.name === cleanName
    ) {
        return data.player;
    }

    return data.characters[cleanName] || null;
}


// --------------------------------------------------
// CHECK REGISTRATION
// --------------------------------------------------

function isContinuityCharacterRegistered(name) {
    return !!getContinuityCharacter(name);
}


// --------------------------------------------------
// SET IDENTITY FIELD
// --------------------------------------------------
//
// Identity fields should only be set from explicit,
// authoritative information.
//
// Existing facts should not be silently replaced.
//
// allowOverride should only be true when the story
// explicitly establishes a lasting change or correction.

function setContinuityIdentityField(
    name,
    field,
    value,
    allowOverride
) {
    const character =
        getContinuityCharacter(name);

    if (!character || !field || value === undefined || value === null) {
        return false;
    }

    const allowedFields = [
        "age",
        "gender",
        "pronouns",
        "species",
        "occupation",
        "background",
        "orientation",
        "home"
    ];

    if (allowedFields.indexOf(field) === -1) {
        return false;
    }

    const cleanValue =
        String(value).trim();

    if (!cleanValue) {
        return false;
    }

    if (
        character.identity[field] === null ||
        character.identity[field] === ""
    ) {
        character.identity[field] = cleanValue;
        return true;
    }

    if (allowOverride === true) {
        character.identity[field] = cleanValue;
        return true;
    }

    return false;
}


// --------------------------------------------------
// SET APPEARANCE FIELD
// --------------------------------------------------

function setContinuityAppearanceField(
    name,
    field,
    value,
    allowOverride
) {
    const character =
        getContinuityCharacter(name);

    if (!character || !field || value === undefined || value === null) {
        return false;
    }

    const allowedFields = [
        "height",
        "build",
        "skin",
        "hair",
        "eyes"
    ];

    if (allowedFields.indexOf(field) === -1) {
        return false;
    }

    const cleanValue =
        String(value).trim();

    if (!cleanValue) {
        return false;
    }

    if (
        character.appearance[field] === null ||
        character.appearance[field] === ""
    ) {
        character.appearance[field] = cleanValue;
        return true;
    }

    if (allowOverride === true) {
        character.appearance[field] = cleanValue;
        return true;
    }

    return false;
}


// --------------------------------------------------
// APPEARANCE LIST FACTS
// --------------------------------------------------

function addContinuityScar(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.appearance.scars,
        value
    );
}


function addContinuityTattoo(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.appearance.tattoos,
        value
    );
}


function addContinuityPermanentTrait(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.appearance.permanentTraits,
        value
    );
}


// --------------------------------------------------
// ABILITIES / POWERS / SKILLS
// --------------------------------------------------

function addContinuityAbility(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.abilities,
        value
    );
}


function addContinuityPower(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.powers,
        value
    );
}


function addContinuitySkill(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.skills,
        value
    );
}


// --------------------------------------------------
// FAMILY / IMPORTANT FACTS
// --------------------------------------------------

function addContinuityFamilyFact(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.familyFacts,
        value
    );
}


function addContinuityImportantFact(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.importantFacts,
        value
    );
}


// --------------------------------------------------
// TEMPORARY STATES
// --------------------------------------------------
//
// Examples:
// - wet hair
// - wearing disguise
// - covered in mud
// - transformed appearance
// - formal clothing
// - temporary glamour
//
// Temporary states do NOT replace permanent identity.

function addContinuityTemporaryState(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character) return false;

    return addUniqueContinuityValue(
        character.temporaryStates,
        value
    );
}


function removeContinuityTemporaryState(name, value) {
    const character =
        getContinuityCharacter(name);

    if (!character || !value) {
        return false;
    }

    const cleanValue =
        String(value).trim();

    const index =
        character.temporaryStates.indexOf(cleanValue);

    if (index === -1) {
        return false;
    }

    character.temporaryStates.splice(index, 1);

    return true;
}


function clearContinuityTemporaryStates(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    character.temporaryStates = [];

    return true;
}


// --------------------------------------------------
// LOCATION TRACKING
// --------------------------------------------------
//
// currentLocation = objective actual location
//
// lastKnownLocation = previous established location
//
// Moving a character updates both.
//
// This does NOT mean every other character knows
// the current location.

function setContinuityLocation(name, location) {
    const character =
        getContinuityCharacter(name);

    if (!character || !location) {
        return false;
    }

    const cleanLocation =
        String(location).trim();

    if (!cleanLocation) {
        return false;
    }

    if (
        character.currentLocation &&
        character.currentLocation !== cleanLocation
    ) {
        character.lastKnownLocation =
            character.currentLocation;
    }

    character.currentLocation =
        cleanLocation;

    return true;
}


function getContinuityLocation(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return null;
    }

    return character.currentLocation;
}


// --------------------------------------------------
// ACTIVE SCENE
// --------------------------------------------------

function setContinuitySceneLocation(location) {
    const data = initCharacterContinuity();

    if (!location) {
        data.activeScene.location = null;
        return true;
    }

    data.activeScene.location =
        String(location).trim();

    return true;
}


function getContinuitySceneLocation() {
    const data = initCharacterContinuity();

    return data.activeScene.location || null;
}


// --------------------------------------------------
// SCENE PARTICIPATION
// --------------------------------------------------

function setContinuityScenePresence(
    name,
    present
) {
    const data = initCharacterContinuity();

    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    character.presentInScene =
        present === true;

    const cleanName =
        character.name;

    const index =
        data.activeScene.participants.indexOf(
            cleanName
        );

    if (
        present === true &&
        index === -1
    ) {
        data.activeScene.participants.push(
            cleanName
        );
    }

    if (
        present !== true &&
        index !== -1
    ) {
        data.activeScene.participants.splice(
            index,
            1
        );
    }

    return true;
}


function isContinuityPresentInScene(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    return character.presentInScene === true;
}


// --------------------------------------------------
// ENTER SCENE
// --------------------------------------------------
//
// Entering a scene can also set the character's
// current location to the active scene location.

function continuityEnterScene(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    const sceneLocation =
        getContinuitySceneLocation();

    if (sceneLocation) {
        setContinuityLocation(
            name,
            sceneLocation
        );
    }

    return setContinuityScenePresence(
        name,
        true
    );
}


// --------------------------------------------------
// LEAVE SCENE
// --------------------------------------------------
//
// Leaving a scene removes scene presence.
//
// It does NOT invent the character's destination.
// Location remains the last established physical
// location until another location is explicitly known.

function continuityLeaveScene(name) {
    return setContinuityScenePresence(
        name,
        false
    );
}


// --------------------------------------------------
// PERCEPTION ABILITIES
// --------------------------------------------------
//
// These must be explicitly established.
//
// Examples:
// super hearing
// enhanced vision
// clairvoyance
// telepathy
// magical sensing
//
// Merely being powerful does not grant all senses.

function addContinuityPerceptionAbility(
    name,
    ability
) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    return addUniqueContinuityValue(
        character.perceptionAbilities,
        ability
    );
}


// --------------------------------------------------
// PERCEPTION DEVICES / METHODS
// --------------------------------------------------
//
// Examples:
// phone call
// radio
// security camera
// microphone
// surveillance feed
// magical scrying device
//
// Possession does not automatically mean active use.

function addContinuityPerceptionDevice(
    name,
    device
) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    return addUniqueContinuityValue(
        character.perceptionDevices,
        device
    );
}


// --------------------------------------------------
// ACTIVE REMOTE PERCEPTION
// --------------------------------------------------
//
// This tracks established remote access that is
// currently relevant.
//
// Example:
// "watching the kitchen security camera"
// "on an active phone call with Elena"
// "using clairvoyance on the throne room"
//
// This prevents a generic ability or device from
// becoming unlimited omniscience.

function addActiveRemotePerception(
    name,
    source
) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    return addUniqueContinuityValue(
        character.activeRemotePerception,
        source
    );
}


function removeActiveRemotePerception(
    name,
    source
) {
    const character =
        getContinuityCharacter(name);

    if (!character || !source) {
        return false;
    }

    const cleanSource =
        String(source).trim();

    const index =
        character.activeRemotePerception.indexOf(
            cleanSource
        );

    if (index === -1) {
        return false;
    }

    character.activeRemotePerception.splice(
        index,
        1
    );

    return true;
}


function clearActiveRemotePerception(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    character.activeRemotePerception = [];

    return true;
}


// --------------------------------------------------
// CAN CHARACTER DIRECTLY PERCEIVE CURRENT SCENE?
// --------------------------------------------------
//
// Physical presence always qualifies.
//
// Remote perception only qualifies if it is
// specifically active and established.
//
// This function deliberately does NOT infer that
// "super hearing" automatically reaches every place.
//
// The Context script decides whether an established
// ability actually covers the present distance and
// circumstances.

function canContinuityDirectlyPerceiveScene(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return false;
    }

    if (character.presentInScene === true) {
        return true;
    }

    if (
        Array.isArray(
            character.activeRemotePerception
        ) &&
        character.activeRemotePerception.length > 0
    ) {
        return true;
    }

    return false;
}


// --------------------------------------------------
// NOTES
// --------------------------------------------------

function addContinuityNote(name, note) {
    const character =
        getContinuityCharacter(name);

    if (!character || !note) {
        return false;
    }

    return addUniqueContinuityValue(
        character.notes,
        note
    );
}


// --------------------------------------------------
// IDENTITY SUMMARY
// --------------------------------------------------

function getContinuityIdentitySummary(character) {
    if (!character) {
        return "";
    }

    let result =
        character.name;

    if (character.isPlayer) {
        result += " [PLAYER]";
    }

    const identity =
        character.identity;

    if (identity.age) {
        result +=
            " | Age: " +
            identity.age;
    }

    if (identity.gender) {
        result +=
            " | Gender: " +
            identity.gender;
    }

    if (identity.pronouns) {
        result +=
            " | Pronouns: " +
            identity.pronouns;
    }

    if (identity.species) {
        result +=
            " | Species: " +
            identity.species;
    }

    if (identity.occupation) {
        result +=
            " | Occupation: " +
            identity.occupation;
    }

    if (identity.background) {
        result +=
            " | Background: " +
            identity.background;
    }

    if (identity.orientation) {
        result +=
            " | Orientation: " +
            identity.orientation;
    }

    if (identity.home) {
        result +=
            " | Home: " +
            identity.home;
    }

    return result;
}


// --------------------------------------------------
// APPEARANCE SUMMARY
// --------------------------------------------------

function getContinuityAppearanceSummary(character) {
    if (!character) {
        return "";
    }

    const appearance =
        character.appearance;

    const parts = [];

    if (appearance.height) {
        parts.push(
            "height: " +
            appearance.height
        );
    }

    if (appearance.build) {
        parts.push(
            "build: " +
            appearance.build
        );
    }

    if (appearance.skin) {
        parts.push(
            "skin: " +
            appearance.skin
        );
    }

    if (appearance.hair) {
        parts.push(
            "hair: " +
            appearance.hair
        );
    }

    if (appearance.eyes) {
        parts.push(
            "eyes: " +
            appearance.eyes
        );
    }

    if (appearance.scars.length) {
        parts.push(
            "scars: " +
            appearance.scars.join("; ")
        );
    }

    if (appearance.tattoos.length) {
        parts.push(
            "tattoos: " +
            appearance.tattoos.join("; ")
        );
    }

    if (appearance.permanentTraits.length) {
        parts.push(
            "permanent traits: " +
            appearance.permanentTraits.join("; ")
        );
    }

    return parts.join(" | ");
}


// --------------------------------------------------
// LOCATION SUMMARY
// --------------------------------------------------

function getContinuityLocationSummary(character) {
    if (!character) {
        return "";
    }

    let result = "";

    if (character.currentLocation) {
        result +=
            "Current location: " +
            character.currentLocation;
    } else {
        result +=
            "Current location: unknown";
    }

    result +=
        " | Present in active scene: " +
        (
            character.presentInScene
                ? "yes"
                : "no"
        );

    if (character.lastKnownLocation) {
        result +=
            " | Previous established location: " +
            character.lastKnownLocation;
    }

    return result;
}


// --------------------------------------------------
// FULL CHARACTER SUMMARY
// --------------------------------------------------

function getCharacterContinuitySummary(name) {
    const character =
        getContinuityCharacter(name);

    if (!character) {
        return "";
    }

    let result =
        getContinuityIdentitySummary(
            character
        );

    const appearance =
        getContinuityAppearanceSummary(
            character
        );

    if (appearance) {
        result +=
            "\nAppearance: " +
            appearance;
    }

    result +=
        "\n" +
        getContinuityLocationSummary(
            character
        );

    if (character.abilities.length) {
        result +=
            "\nAbilities: " +
            character.abilities.join("; ");
    }

    if (character.powers.length) {
        result +=
            "\nPowers: " +
            character.powers.join("; ");
    }

    if (character.skills.length) {
        result +=
            "\nSkills: " +
            character.skills.join("; ");
    }

    if (character.familyFacts.length) {
        result +=
            "\nFamily facts: " +
            character.familyFacts.join("; ");
    }

    if (character.importantFacts.length) {
        result +=
            "\nImportant facts: " +
            character.importantFacts.join("; ");
    }

    if (character.temporaryStates.length) {
        result +=
            "\nTemporary states: " +
            character.temporaryStates.join("; ");
    }

    if (character.perceptionAbilities.length) {
        result +=
            "\nEstablished perception abilities: " +
            character.perceptionAbilities.join("; ");
    }

    if (character.perceptionDevices.length) {
        result +=
            "\nEstablished perception devices/methods: " +
            character.perceptionDevices.join("; ");
    }

    if (character.activeRemotePerception.length) {
        result +=
            "\nCurrently active remote perception: " +
            character.activeRemotePerception.join("; ");
    }

    if (character.notes.length) {
        result +=
            "\nNotes: " +
            character.notes.join("; ");
    }

    return result;
}


// --------------------------------------------------
// ALL CONTINUITY RECORDS
// --------------------------------------------------

function getCharacterContinuityList() {
    const data =
        initCharacterContinuity();

    const sections = [];

    if (data.player) {
        sections.push(
            getCharacterContinuitySummary(
                data.player.name
            )
        );
    }

    const names =
        Object.keys(
            data.characters
        );

    for (
        let i = 0;
        i < names.length;
        i++
    ) {
        sections.push(
            getCharacterContinuitySummary(
                names[i]
            )
        );
    }

    if (sections.length === 0) {
        return "No characters are currently registered in Character Continuity & Identity.";
    }

    return sections.join("\n\n");
}


// --------------------------------------------------
// ACTIVE SCENE SUMMARY
// --------------------------------------------------

function getCharacterContinuitySceneSummary() {
    const data =
        initCharacterContinuity();

    let result =
        "Active scene location: " +
        (
            data.activeScene.location ||
            "unknown"
        );

    if (
        data.activeScene.participants.length
    ) {
        result +=
            "\nCharacters physically present: " +
            data.activeScene.participants.join(", ");
    } else {
        result +=
            "\nCharacters physically present: none currently registered";
    }

    return result;
}
